    def upload_file(self, name: str, content: bytes, *, media_type: str = "application/octet-stream") -> CodeFile:
        """Uploads a file (at most 100 MB) the key's sessions may attach; it mounts read-only at /mnt/session/uploads/<name>."""
        if "\r" in media_type or "\n" in media_type:
            raise CloudError("cave_media_type_invalid", "The media type is not valid.")
        boundary = "caveman-" + uuid.uuid4().hex
        quoted = name.replace("\\", "_").replace('"', "_").replace("\r", "_").replace("\n", "_")
        head = f'--{boundary}\r\nContent-Disposition: form-data; name="file"; filename="{quoted}"\r\nContent-Type: {media_type}\r\n\r\n'.encode()
        body = head + content + f"\r\n--{boundary}--\r\n".encode()
        headers = {"authorization": "Bearer " + self.api_key, "content-type": "multipart/form-data; boundary=" + boundary}
        request = urllib.request.Request(self._url("/code/files", None), data=body, headers=headers, method="POST")
        try:
            response = self._opener.open(request, timeout=max(self.timeout_seconds, 120))
        except urllib.error.HTTPError as error:
            response = error
        with response:
            status, raw = response.status, response.read(_LIMIT + 1)
        if not 200 <= status < 300:
            raise _failure(status, raw)
        try:
            return cast(CodeFile, json.loads(raw))
        except (ValueError, UnicodeError):
            raise CloudError("cave_response_invalid", "The response is not JSON.", status) from None

    def download_file(self, file_id: str) -> bytes:
        """Downloads a file's bytes."""
        path = f"/code/files/{urllib.parse.quote(file_id, safe='')}/content"
        request = urllib.request.Request(self._url(path, None), headers={"authorization": "Bearer " + self.api_key}, method="GET")
        try:
            response = self._opener.open(request, timeout=max(self.timeout_seconds, 120))
        except urllib.error.HTTPError as error:
            with error:
                raise _failure(error.code, error.read(_LIMIT + 1)) from None
        with response:
            return bytes(response.read())

    def stream_events(self, session_id: str, *, after: int | None = None) -> Iterator[CodeStreamEvent]:
        """Streams a session's events after `after` (server-sent events). The server ends a stream after 15 minutes, or once an ended session has nothing more; call again with the last seq to continue."""
        path = f"/code/sessions/{urllib.parse.quote(session_id, safe='')}/events/stream"
        request = urllib.request.Request(self._url(path, {"after": after}), headers={"authorization": "Bearer " + self.api_key, "accept": "text/event-stream"}, method="GET")
        try:
            response = self._opener.open(request, timeout=max(self.timeout_seconds, 60))
        except urllib.error.HTTPError as error:
            with error:
                raise _failure(error.code, error.read(_LIMIT + 1)) from None
        with response:
            seq, kind, data = "", "message", ""
            for raw in response:
                line = raw.decode().rstrip("\r\n")
                if line.startswith("id: "):
                    seq = line[4:]
                elif line.startswith("event: "):
                    kind = line[7:]
                elif line.startswith("data: "):
                    data += line[6:]
                elif line == "":
                    if kind == "error":
                        failure = json.loads(data or "{}")
                        raise CloudError(str(failure.get("code", "cave_stream_failed")), "The event stream ended with an error.")
                    if seq:
                        yield {"seq": int(seq), "type": kind, "data": json.loads(data or "{}")}
                    seq, kind, data = "", "message", ""
